// -----------------------------------------------------------------------------
// orient_quantizer.sv  --  angle discretisation (Section 4.5.4, Table 2)
//
//   quadrant  = from the signs of (m10, m01):  0:(+,+) 1:(-,+) 2:(-,-) 3:(+,-)
//   fold      = |m10|, |m01|  (first quadrant)
//   comparator k:  |m10| * TAN_k  >  |m01| << FRAC_BITS      (TAN_k = fixed-point tan)
//   sector    = lowest k with a hit (priority encoder); no hit -> last sector (NQ-1)
//
// The constants come from orient_tan_table.svh (generated by gen_vectors.py; it holds
// the sector count, rounding mode and fixed-point width).  The constant multiplies
// are written with '*': synthesis maps them to DSPs or shift-and-add networks
// (add (* use_dsp = "no" *) to force LUT shift-add as in the paper).
//   latency = 4 clocks:  Q0 abs/quadrant | Q1 products | Q2 compare | Q3 encode
// -----------------------------------------------------------------------------
module orient_quantizer #(
    parameter int MW     = 22,
    parameter int N_SECT = 64,
    parameter int NQ     = N_SECT / 4,
    parameter int SEC_W  = $clog2(N_SECT / 4),
    parameter int TAG_W  = 1
)(
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  valid_in,
    input  logic signed [MW-1:0]  m10,
    input  logic signed [MW-1:0]  m01,
    input  logic [TAG_W-1:0]      tag_in,
    output logic                  valid_out,
    output logic [1:0]            quadrant,
    output logic [SEC_W-1:0]      sector,
    output logic [TAG_W-1:0]      tag_out
);
`include "orient_tan_table.svh"     // FRAC_BITS, TBL_NSECT, N_CMP, TC_W, TAN_TABLE

    initial begin
        if (TBL_NSECT != N_SECT) begin
            $display("orient_quantizer: orient_tan_table.svh was generated for %0d sectors, N_SECT=%0d",
                     TBL_NSECT, N_SECT);
            $finish;
        end
    end

    // ---- Q0: quadrant and magnitudes -------------------------------------------
    logic [MW-1:0] a10_w, a01_w;
    assign a10_w = m10[MW-1] ? (~m10 + 1'b1) : m10;
    assign a01_w = m01[MW-1] ? (~m01 + 1'b1) : m01;

    logic                    v0;
    logic [1:0]              q0;
    logic [MW-1:0]           a10_0;
    logic [MW+FRAC_BITS-1:0] rhs0;
    logic [TAG_W-1:0]        tg0;

    always_ff @(posedge clk) begin
        v0    <= rst_n & valid_in;
        q0    <= {m01[MW-1], m01[MW-1] ^ m10[MW-1]};
        a10_0 <= a10_w;
        rhs0  <= {a01_w, {FRAC_BITS{1'b0}}};
        tg0   <= tag_in;
    end

    // ---- Q1: |m10| * TAN_k ---------------------------------------------------------
    logic [MW+TC_W-1:0]      prod [0:N_CMP-1];
    logic                    v1;
    logic [1:0]              q1;
    logic [MW+FRAC_BITS-1:0] rhs1;
    logic [TAG_W-1:0]        tg1;

    genvar k;
    generate
        for (k = 0; k < N_CMP; k++) begin : g_prod
            logic [TC_W-1:0] c;
            assign c = TAN_TABLE[k*TC_W +: TC_W];
            always_ff @(posedge clk) prod[k] <= a10_0 * c;
        end
    endgenerate

    always_ff @(posedge clk) begin
        v1   <= rst_n & v0;
        q1   <= q0;
        rhs1 <= rhs0;
        tg1  <= tg0;
    end

    // ---- Q2: comparators -------------------------------------------------------
    logic [N_CMP-1:0] hit;
    logic             v2;
    logic [1:0]       q2;
    logic [TAG_W-1:0] tg2;

    generate
        for (k = 0; k < N_CMP; k++) begin : g_cmp
            always_ff @(posedge clk) hit[k] <= (prod[k] > rhs1);
        end
    endgenerate

    always_ff @(posedge clk) begin
        v2  <= rst_n & v1;
        q2  <= q1;
        tg2 <= tg1;
    end

    // ---- Q3: priority encoder -------------------------------------------------------
    logic [SEC_W-1:0] sec_c;
    always_comb begin
        sec_c = SEC_W'(NQ - 1);
        for (int j = N_CMP - 1; j >= 0; j--) begin
            if (hit[j]) sec_c = SEC_W'(j);
        end
    end

    logic             v3;
    logic [1:0]       q3;
    logic [SEC_W-1:0] s3;
    logic [TAG_W-1:0] tg3;

    always_ff @(posedge clk) begin
        v3  <= rst_n & v2;
        q3  <= q2;
        s3  <= sec_c;
        tg3 <= tg2;
    end

    assign valid_out = v3;
    assign quadrant  = q3;
    assign sector    = s3;
    assign tag_out   = tg3;
endmodule
